//! RIIR 3: the runtime offset contract. How late the run is, and when the next
//! flag, the end of the group and the end of the rundown are now expected, as
//! upstream's server computes them (fixture generated by driving its
//! runtimeState through a script of operator actions), against our
//! Runtime::snapshot. Every screen reads these from the runtime-data packet.
//!
//! RIIR 4 adds roll: the wall clock picks and advances the event. Each step
//! ticks before and after it, as upstream's runtime.service does.

use ontime_core::rundown::Rundown;
use ontime_core::runtime::{Command, Runtime};
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
#[serde(tag = "do", rename_all = "lowercase")]
enum Action {
    Start { id: String },
    Load { id: String },
    Addtime { amount: i64 },
    Mode { mode: String },
    Pause,
    Resume,
    Stop,
    Tick,
    Roll,
}

#[derive(Deserialize)]
struct Step {
    at: i64,
    #[serde(flatten)]
    action: Action,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    epoch: i64,
    rundown: Rundown,
    steps: Vec<Step>,
    expected: Value,
}

#[derive(Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

/// Upstream's own results that this fork deliberately does not follow, with why.
/// Each is a `(case, field)`; anything else that differs fails the test.
const DELIBERATE: &[(&str, &str, &str)] = &[
    // When roll moves on to the flagged event, upstream reports no next flag
    // (eventFlag null, which we match) but keeps the flag start it worked out
    // while the previous event ran: its waiting path never recomputes it. A
    // start for a flag that is not there is stale, so ours is null.
    (
        "roll waits through a gap after an event",
        "offset.expectedFlagStart",
        "stale upstream value: the flag is now the loaded event",
    ),
    (
        "roll into the next day",
        "offset.expectedFlagStart",
        "stale upstream value: the flag is now the loaded event",
    ),
];

fn command(action: Action) -> Option<Command> {
    match action {
        Action::Start { id } => Some(Command::StartId(id)),
        Action::Load { id } => Some(Command::LoadId(id)),
        Action::Addtime { amount } => Some(Command::AddTime(amount)),
        // through the websocket parser, so the tag the editor sends is covered too
        Action::Mode { mode } => Command::parse("offsetmode", Some(&Value::String(mode))),
        Action::Pause => Some(Command::Pause),
        Action::Resume => Some(Command::Start),
        Action::Stop => Some(Command::Stop),
        Action::Roll => Some(Command::Roll),
        Action::Tick => None,
    }
}

fn actual(snapshot: &Value, section: &str, field: &str) -> Value {
    match section {
        // upstream keeps the whole entry; the id is what identifies it
        "eventFlag" | "groupNow" | "eventNow" => {
            snapshot[section].get("id").cloned().unwrap_or(Value::Null)
        }
        _ => snapshot[section].get(field).cloned().unwrap_or(Value::Null),
    }
}

#[test]
fn snapshot_offsets_match_upstream() {
    let fixture: Fixture =
        serde_json::from_str(include_str!("fixtures/runtime_offset.json")).unwrap();
    let mut failures = Vec::new();

    for case in fixture.cases {
        let mut rundown = case.rundown;
        rundown.recompute();
        let mut runtime = Runtime::default();
        let mut now = case.epoch;
        for step in case.steps {
            now = case.epoch + step.at;
            runtime.on_tick(&rundown, now, 0);
            if let Some(command) = command(step.action) {
                runtime.apply(command, &rundown, now, 0);
            }
            runtime.on_tick(&rundown, now, 0);
        }
        let snapshot = runtime.snapshot(&rundown, now, 0);

        let mut compare = |section: &str, field: &str, want: &Value| {
            if DELIBERATE
                .iter()
                .any(|(name, key, _)| *name == case.name && *key == format!("{section}.{field}"))
            {
                return;
            }
            let got = actual(&snapshot, section, field);
            let same = match (got.as_f64(), want.as_f64()) {
                (Some(a), Some(b)) => a == b,
                _ => got == *want,
            };
            if !same {
                failures.push(format!(
                    "{} / {section}.{field}: upstream {want}, ours {got}",
                    case.name
                ));
            }
        };

        for section in ["offset", "rundown", "timer"] {
            if let Some(fields) = case.expected[section].as_object() {
                for (field, want) in fields {
                    compare(section, field, want);
                }
            }
        }
        for section in ["eventFlag", "groupNow", "eventNow"] {
            compare(section, "id", &case.expected[section]);
        }
    }

    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
